{
  "skill": "trace:trace"
}

{
  "command": "cat GLOSSARY.md docs/adr/0005-*.md docs/adr/0006-*.md docs/adr/0007-*.md docs/adr/0008-*.md; ls docs/adr; gh issue view 1 --comments; gh pr view 2 --comments; git log --oneline main..HEAD; git diff main --stat",
  "description": "Read related docs, issue, PR"
}

{
  "command": "gh issue view 1 --comments 2>&1; echo ----; gh pr view 2 --comments 2>&1; echo ----; git diff main",
  "description": "View issue, PR, and diff"
}

