diff --git a/plugins/trace/scripts/lib/status.mjs b/plugins/trace/scripts/lib/status.mjs
index 2c1f2ad..203710f 100644
--- a/plugins/trace/scripts/lib/status.mjs
+++ b/plugins/trace/scripts/lib/status.mjs
@@ -84,7 +84,7 @@ export function traceStatus(cwd, world) {
     ['read', unread],
     ['track', null],
     ['branch', null],
-    ['implement', world.git.committed(root, n) ? null : `no commit on this branch references #${n} yet. Implement step: build it test-first (implement, tdd), committing with #${n} in each message.`],
+    ['implement', world.git.committed(root, n) ? null : `no commit on this branch references #${n} yet. Implement step: build it test-first (tdd), committing with #${n} in each message.`],
     ['review', reviewWhy(pr, branch, n)],
     [
       'update',
@@ -112,7 +112,7 @@ function reviewWhy(pr, branch, n) {
   if (pr === null) return `GitHub could not say whether ${branch} has a PR; check \`gh auth status\` and the network.`
   if (pr !== 'NONE' && pr.state === 'OPEN') return null
   const was = pr === 'NONE' ? '' : pr.state === 'CLOSED' ? `PR #${pr.n} for ${branch} was closed unmerged. ` : `PR #${pr.n} for ${branch} was merged, but #${n} is still open: a PR closes its issue only when it merges into the default branch. `
-  return `${was}Review step: open a PR for ${branch} that says Closes #${n} (pr), and review it (code-review).`
+  return `${was}Review step: review ${branch} (/code-review, mattpocock-skills:code-review), then open a PR for it that says Closes #${n} (pr).`
 }

 /** @param {string} state a check's state @returns {Outcome} */
diff --git a/plugins/trace/scripts/lib/trace.mjs b/plugins/trace/scripts/lib/trace.mjs
index 6208fd2..723edd3 100644
--- a/plugins/trace/scripts/lib/trace.mjs
+++ b/plugins/trace/scripts/lib/trace.mjs
@@ -208,14 +208,14 @@ export function linkedIssue(root, branch, { git, github }) {
   }
   const n = branchIssue(branch)
   if (!n) {
-    return { why: `the branch ${branch ?? '(detached HEAD)'} names no issue. Track step: open an issue (to-tickets), then \`gh issue develop <n> --checkout\`.` }
+    return { why: `the branch ${branch ?? '(detached HEAD)'} names no issue. Track step: open an issue (\`gh issue create\`, with acceptance criteria), then \`gh issue develop <n> --checkout\`.` }
   }
   const state = github.issueState(root, n)
   if (state === 'OPEN') return { n }
   if (state === null) {
     return { why: `GitHub could not say whether issue #${n} is open; check \`gh auth status\`, the network, and that origin is on GitHub. Track step: the work waits for an open issue; ${BYPASS_HINT}.` }
   }
-  return { why: `#${n} is ${state === 'CLOSED' ? 'a closed issue' : 'not an open issue'}. Track step: open an issue for this change (to-tickets) and work on its branch.` }
+  return { why: `#${n} is ${state === 'CLOSED' ? 'a closed issue' : 'not an open issue'}. Track step: open an issue for this change (\`gh issue create\`, with acceptance criteria) and work on its branch.` }
 }

 // --- the commit and PR gates -----------------------------------------------------
diff --git a/plugins/trace/skills/trace/SKILL.md b/plugins/trace/skills/trace/SKILL.md
index fd327e0..3dabff7 100644
--- a/plugins/trace/skills/trace/SKILL.md
+++ b/plugins/trace/skills/trace/SKILL.md
@@ -9,14 +9,16 @@ Every change, code or docs or config, ties to one GitHub issue from start to fin

 | Step | Do it with | Done when |
 |---|---|---|
-| **Read** | `GLOSSARY.md` and the ADRs the change touches | you can name the decisions that bind the change |
-| **Track** | `to-tickets`, or `grilling` then `to-spec` first when the change is unclear | an open issue states what to build and how to verify it |
+| **Read** | the related docs: `GLOSSARY.md`, every active ADR (one with `applies-to:` only for the paths it names), and, once you are on its branch, the linked issue with its comments and the `docs/` files it links | this agent itself, not its parent, has read each in full since its last compaction: the band shows the docs read |
+| **Track** | `gh issue create` with an `## Acceptance criteria` section; `grilling` first when the change is unclear. To split larger work, ask the human to run `/to-spec` and `/to-tickets` | an open issue states what to build and how to verify it |
 | **Branch** | `gh issue develop <n> --checkout`, with `--base <blocker's branch>` while the blocker's PR awaits merge | you are on `<n>-<slug>` |
-| **Implement** | `implement` and `tdd`; `diagnosing-bugs` for a hard bug | every acceptance criterion passes and every commit message carries `#<n>` |
-| **Review** | `/code-review` for bugs, Matt's `code-review` for standards and spec, then `pr` for the body | a PR whose body says `Closes #<n>` |
+| **Implement** | `tdd`; `diagnosing-bugs` for a hard bug. The human may run `/implement <n>` instead | every acceptance criterion passes and every commit message carries `#<n>` |
+| **Review** | `/code-review` for bugs, and `mattpocock-skills:code-review` since the branch's base for standards and spec, with `GLOSSARY.md` and the active ADRs among its standards; then `pr` for the body | a PR whose body says `Closes #<n>` |
 | **Update** | `gh issue comment <n>` | the issue shows this round's progress, decisions and verification |
 | **Close** | the human merges | the issue is closed by its PR, or closed with a state reason and a comment |

+Review and fix run in rounds. Answer every finding with a fix or, in the progress comment, a reason. Fix the finding's whole class, every instance of it. After the first round, review only the new diff. After three rounds, step back: reconsider the approach and ask the human before a fourth.
+
 The issue is the source of truth across compaction, resumes and subagents: when memory and the issue disagree, reread the issue.

 Merging is the human's step. Your work is done when the PR is ready for review.
